function resolveFile(f) {
  if (!f) return f;
  if (f.indexOf('data:image/') === 0) return f;
  if (f.indexOf('assets/') === 0 || f.indexOf('http') === 0) return f;
  if (__imgCache[f]) return __imgCache[f];
  // not embedded - the loose files live in assets/ next to this script
  return 'assets/' + f;
}
